package br.com.barbeirofinanceiro.application.despesa;
import br.com.barbeirofinanceiro.domain.despesarecorrente.*; import br.com.barbeirofinanceiro.domain.movimentacao.FormaPagamento; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
public record DespesaRecorrenteResponse(UUID id,String descricao,BigDecimal valor,UUID categoriaId,short diaVencimento,Periodicidade periodicidade,FormaPagamento formaPagamento,LocalDate dataInicio,LocalDate dataFim,boolean ativa,Instant createdAt,Instant updatedAt){public static DespesaRecorrenteResponse from(DespesaRecorrente d){return new DespesaRecorrenteResponse(d.getId(),d.getDescricao(),d.getValor(),d.getCategoria().getId(),d.getDiaVencimento(),d.getPeriodicidade(),d.getFormaPagamento(),d.getDataInicio(),d.getDataFim(),d.isAtiva(),d.getCreatedAt(),d.getUpdatedAt());}}
